let classes: Int32Array | undefined;

/** The index of the range holding `codePoint` in the 3-wide table, or -1. */
function findClasses(codePoint: number): number {
  classes ??= Int32Array.from(classesData());
  let low = 0;
  let high = classes.length / 3 - 1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const at = middle * 3;
    if (codePoint < (classes[at] as number)) high = middle - 1;
    else if (codePoint > (classes[at + 1] as number)) low = middle + 1;
    else return at;
  }
  return -1;
}

/** The canonical combining class of `codePoint`: 0 for a starter. */
export function combiningClass(codePoint: number): number {
  const at = findClasses(codePoint);
  return at === -1 ? 0 : ((classes as Int32Array)[at + 2] as number);
}

