let exclusions: Int32Array | undefined;

/** The index of the range holding `codePoint` in the 2-wide table, or -1. */
function findExclusions(codePoint: number): number {
  exclusions ??= Int32Array.from(exclusionsData());
  let low = 0;
  let high = exclusions.length / 2 - 1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const at = middle * 2;
    if (codePoint < (exclusions[at] as number)) high = middle - 1;
    else if (codePoint > (exclusions[at + 1] as number)) low = middle + 1;
    else return at;
  }
  return -1;
}

/** Whether `codePoint` is Full_Composition_Exclusion: never the result of canonical composition. */
export function isCompositionExcluded(codePoint: number): boolean {
  return findExclusions(codePoint) !== -1;
}
